  'http://www.domain1.com:3000/login?user=admin', true); xhr.send(); 2.）中间件服务器： var express = require('express'); var proxy =
  require('http-proxy-middleware'); var app = express(); app.use('/', proxy({ //
  代理跨域目标接口 target: 'http://www.domain2.com:8080', changeOrigin: true, //
  修改响应头信息，实现跨域并允许带 cookie onProxyRes: function(proxyRes, req, res)
  { res.header('Access-Control-Allow-Origin', 'http://www.domain1.com');
  res.header('Access-Control-Allow-Credentials', 'true'); }, //
  修改响应信息中的 cookie 域名 cookieDomainRewrite: 'www.domain1.com' //
  可以为 false，表示不修改 })); app.listen(3000); console.log('Proxy server is
  listen at port 3000...'); 3.）Nodejs 后台同（六：nginx） 2、 vue 框架的跨域（1
  次跨域） 利用 node + webpack + webpack-dev-server
  代理接口跨域。在开发环境下，由于 vue 渲染服务和接口代理服务都是
